import {expect as baseExpect} from '@playwright/test'
import {randomUUID,randomBytes} from 'node:crypto'
import {mkdirSync,writeFileSync} from 'node:fs'
import {expectSuccess,expectDatabaseError} from '../../scripts/staging/assertions.mjs'
const expect=baseExpect.configure({timeout:30000})
export async function prepareCrew(actors,label='SYNTHETIC crew coordination'){
 const company=randomUUID(),tag=label+' '+company.slice(0,6)
 const rpc=async(role,fn,command,p={})=>expectSuccess(await actors[role].client.rpc(fn,{command,p:{companyId:company,requestId:randomUUID(),...p}}))
 await rpc('OWNER','ts_command','create_company',{id:company,name:tag})
 for(const role of ['WORKER','SUPERVISOR']){const token=randomBytes(32).toString('hex');await rpc('OWNER','ts_command','invite',{email:actors[role].email,role:role.toLowerCase(),token});await rpc(role,'ts_command','accept_invitation',{token})}
 const site=await rpc('SUPERVISOR','ts_site_command','create',{id:randomUUID(),document:{name:tag,address:'SYNTHETIC coordination bay',instructions:''}})
 let brief=await rpc('SUPERVISOR','ts_site_command','create_brief',{id:randomUUID(),siteId:site.id})
 brief=await rpc('SUPERVISOR','ts_brief_command','save',{id:brief.id,revision:brief.revision,document:{...brief.document,date:'2026-09-23',task:'SYNTHETIC move materials',contact:'Synthetic radio contact',jurisdiction:'CA-ON',workplace:'construction',confirmed:true,crew:[actors.WORKER.id],attendance:[actors.WORKER.id],briefingNote:'SYNTHETIC discuss route',steps:[{id:randomUUID(),task:'Move materials',hazard:'SYNTHETIC blocked route',control:'SYNTHETIC proposed clearance',controlState:'proposed',responsible:actors.WORKER.id,unresolved:true}]}})
 await rpc('SUPERVISOR','ts_brief_command','record',{id:brief.id,revision:brief.revision})
 const action=expectSuccess(await actors.OWNER.client.from('ts_actions').select('*').eq('brief_id',brief.id).single())
 return {company,tag,siteId:site.id,briefId:brief.id,version:brief.revision,actionId:action.id}
}
export async function crewWorkflow({browser,origin,actors,options={},capture=async()=>{},record=()=>{}}){
 let stage='fixtures';const contexts=[]
 const mark=s=>{stage=s}
 const fixture=await prepareCrew(actors),{company,briefId,version,actionId}=fixture
 const rpc=(role,fn,command,p={})=>actors[role].client.rpc(fn,{command,p:{companyId:company,requestId:randomUUID(),...p}})
 const cmd=(r,n,p)=>rpc(r,'ts_command',n,p).then(expectSuccess),brief=(r,n,p)=>rpc(r,'ts_brief_command',n,{id:briefId,...p}).then(expectSuccess)
 const rows=(role,table,key,id)=>actors[role].client.from(table).select('*').eq(key,id).then(expectSuccess)
 const read=async()=>(await rows('OWNER','ts_briefs','id',briefId))[0],action=async()=>(await rows('OWNER','ts_actions','id',actionId))[0]
 const events=()=>actors.OWNER.client.from('ts_events').select('*').eq('entity_id',actionId).eq('kind','action_updated').order('id').then(expectSuccess)
 const work='/my-work?company='+company,crew=work+'&view=crew',actions='/actions?'+new URLSearchParams({company,mine:'0',focus:actionId,from:crew})
 async function login(role){const {localOnly,...settings}=options,c=await browser.newContext({viewport:{width:390,height:844},...settings});contexts.push(c);if(localOnly)await c.route('**/*',r=>[origin,actors[role].apiOrigin].includes(new URL(r.request().url()).origin)?r.continue():r.abort());const p=await c.newPage();p.setDefaultTimeout(30000);p.setDefaultNavigationTimeout(90000);await p.goto(origin+'/auth/login');await p.getByLabel('Email',{exact:true}).fill(actors[role].email);await p.getByLabel('Password',{exact:true}).fill(actors[role].password);await p.getByRole('button',{name:'Sign In',exact:true}).click();await p.waitForURL('**/dashboard');return p}
 async function revise(){let b=await read();b=await brief('SUPERVISOR','revise',{revision:b.revision});b=await brief('SUPERVISOR','save',{revision:b.revision,document:{...b.document,briefingNote:'SYNTHETIC revised discussion',steps:[{...b.document.steps[0],control:'SYNTHETIC revised proposal '+b.revision}]}});await brief('SUPERVISOR','record',{revision:b.revision});return b.revision}
 const screen=async(p,n)=>{expect(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await capture(p,n)}
 try{
  const worker=await login('WORKER'),supervisor=await login('SUPERVISOR'),stale=await login('SUPERVISOR')
  mark('personal-and-supervisor-counts');await worker.goto(origin+work);await expect(worker.getByRole('status').filter({hasText:'1 briefings awaiting your response'})).toBeVisible();await expect(worker.getByRole('status').filter({hasText:'1 outstanding actions assigned to you'})).toBeVisible();await screen(worker,'my-work');await worker.getByRole('link',{name:'Open site',exact:true}).first().click();await worker.getByRole('link',{name:'Back to My work',exact:true}).click();await expect(worker).toHaveURL(origin+work)
  await supervisor.goto(origin+crew);await expect(supervisor.getByText('0 acknowledged · 1 awaiting acknowledgement',{exact:true})).toBeVisible()
  mark('keyboard-brief-link');const link=worker.locator('a[href^="/briefs/'+briefId+'?"]');await link.focus();await worker.keyboard.press('Shift+Tab');await worker.keyboard.press('Tab');await expect(link).toBeFocused();expect(await link.evaluate(e=>getComputedStyle(e).outlineStyle)).not.toBe('none');await worker.keyboard.press('Enter');await expect(worker.getByRole('button',{name:'Acknowledge this version',exact:true})).toBeVisible()
  const original=(await rows('OWNER','ts_brief_versions','brief_id',briefId)).find(v=>v.version===version)
  mark('stale-acknowledgement');const second=await revise();await worker.getByRole('button',{name:'Acknowledge this version',exact:true}).click();await expect(worker.getByRole('alert').filter({hasText:'newer version'})).toBeVisible();expect(await rows('OWNER','ts_brief_acknowledgements','brief_id',briefId)).toHaveLength(0)
  await worker.getByRole('link',{name:'Open current brief',exact:true}).click();await expect(worker.getByText('Recorded daily brief · version '+second,{exact:true})).toBeVisible()
  mark('acknowledgement-lost-response');let lost=false;const api=origin+'/api/briefs';await worker.context().route(api,async r=>{if(r.request().postDataJSON()?.command==='acknowledge'&&!lost){lost=true;expect((await r.fetch()).status()).toBe(200);await r.abort()}else await r.continue()})
  await worker.getByRole('button',{name:'Acknowledge this version',exact:true}).click();await expect(worker.getByRole('button',{name:'Retry same operation',exact:true})).toBeVisible();await worker.getByRole('button',{name:'Retry same operation',exact:true}).click();await expect(worker.getByRole('status').filter({hasText:'Your acknowledgement is recorded for version '+second})).toBeVisible();await worker.context().unroute(api)
  const acks=await rows('OWNER','ts_brief_acknowledgements','brief_id',briefId);expect(acks).toHaveLength(1);expect(acks[0].version).toBe(second);expect(acks[0].user_id).toBe(actors.WORKER.id);expect(acks[0].acknowledged_at).toBeTruthy()
  await worker.getByRole('link',{name:'Back to My work',exact:true}).click();await expect(worker.getByText('No briefings awaiting your response.',{exact:false})).toBeVisible();await worker.reload();await expect(worker.getByRole('status').filter({hasText:'0 briefings awaiting your response'})).toBeVisible()
  await supervisor.reload();await expect(supervisor.getByText('1 acknowledged · 0 awaiting acknowledgement',{exact:true})).toBeVisible()
  mark('new-recorded-version');const third=await revise();await worker.reload();await expect(worker.getByRole('status').filter({hasText:'1 briefings awaiting your response'})).toBeVisible();await supervisor.goto(origin+'/briefs/'+briefId+'?version='+second);await expect(supervisor.getByRole('link',{name:'Read newest recorded version',exact:true})).toBeVisible();expect((await rows('OWNER','ts_brief_versions','brief_id',briefId)).find(v=>v.version===version)).toEqual(original);expect(await rows('OWNER','ts_brief_acknowledgements','brief_id',briefId)).toEqual(acks)
  mark('assignment-retry-and-concurrency');await supervisor.goto(origin+actions);await stale.goto(origin+actions);await supervisor.getByText('Assignment, due date and immediate controls',{exact:true}).click();await supervisor.getByLabel('Responsible member',{exact:true}).selectOption(actors.SUPERVISOR.id)
  const before=await events();let assignmentLost=false;const actionApi=origin+'/api/workspace';await supervisor.context().route(actionApi,async r=>{if(r.request().postDataJSON()?.command==='update_action'&&!assignmentLost){assignmentLost=true;expect((await r.fetch()).status()).toBe(200);await r.abort()}else await r.continue()})
  await supervisor.getByRole('button',{name:'Save progress',exact:true}).click();await expect(supervisor.getByRole('button',{name:'Retry action update',exact:true})).toBeVisible();await supervisor.getByRole('button',{name:'Retry action update',exact:true}).click();await expect(supervisor.getByText('Action update saved.',{exact:true})).toBeVisible();await supervisor.context().unroute(actionApi);expect(await events()).toHaveLength(before.length+1)
  await stale.getByLabel('Progress or resolution notes',{exact:true}).fill('SYNTHETIC losing editor input');await stale.getByRole('button',{name:'Save progress',exact:true}).click();await expect(stale.getByRole('alert').filter({hasText:'newer version'})).toBeVisible();await expect(stale.getByLabel('Progress or resolution notes',{exact:true})).toHaveValue('SYNTHETIC losing editor input')
  await worker.goto(origin+work);await expect(worker.getByText('Nothing assigned to you needs follow-up.',{exact:true})).toBeVisible();await supervisor.reload();await supervisor.getByText('Action history',{exact:true}).click();await expect(supervisor.getByText('Assignment:',{exact:false})).toBeVisible();await supervisor.getByRole('link',{name:'Back to My work',exact:true}).click();await expect(supervisor).toHaveURL(origin+crew)
  let a=await action();const update={id:actionId,revision:a.revision,state:'open',responsibleId:actors.WORKER.id,controls:a.controls,resolution:a.resolution,targetDate:''}
  expectDatabaseError(await rpc('WORKER','ts_command','update_action',update),'TS_denied');a=await cmd('SUPERVISOR','update_action',update)
  expectDatabaseError(await rpc('WORKER','ts_command','update_action',{...update,revision:a.revision,state:'closed',resolution:'SYNTHETIC denied close'}),'TS_denied')
  mark('revoked-membership');await cmd('OWNER','member',{userId:actors.WORKER.id,role:'remove'});await supervisor.goto(origin+crew);await expect(supervisor.getByRole('status').filter({hasText:'1 actions need reassignment'})).toBeVisible();await screen(supervisor,'crew-responses');await supervisor.locator('a[href^="/actions?"]').filter({hasText:'SYNTHETIC blocked route'}).click();await expect(supervisor.getByText('Assignee no longer has access.',{exact:false})).toBeVisible();await supervisor.getByText('Assignment, due date and immediate controls',{exact:true}).click();await supervisor.getByLabel('Responsible member',{exact:true}).selectOption(actors.SUPERVISOR.id);await supervisor.getByRole('button',{name:'Save progress',exact:true}).click();await expect(supervisor.getByText('Action update saved.',{exact:true})).toBeVisible();await supervisor.reload();expect((await action()).responsible_id).toBe(actors.SUPERVISOR.id)
  const history=await events();expect(history.at(-1).before_value.responsible_id).toBe(actors.WORKER.id)
  await supervisor.goto(origin+crew);await expect(supervisor.getByRole('status').filter({hasText:'0 actions need reassignment'})).toBeVisible();await worker.goto(origin+work);await expect(worker.getByRole('heading',{name:'Company access unavailable',exact:true})).toBeVisible()
  for(const table of ['ts_brief_participation','ts_brief_response_summary','ts_action_ownership'])expect(await rows('WORKER',table,'company_id',company)).toHaveLength(0)
  expectDatabaseError(await rpc('WORKER','ts_brief_command','acknowledge',{id:briefId,version:third}),'TS_denied')
  const other=randomUUID();await cmd('OWNER','create_company',{id:other,name:'SYNTHETIC unrelated crew'});await supervisor.goto(origin+'/my-work?company='+other);await expect(supervisor.getByRole('heading',{name:'Company access unavailable',exact:true})).toBeVisible()
  expect((await rows('OWNER','ts_brief_versions','brief_id',briefId)).find(v=>v.version===version)).toEqual(original)
  record('Crew personal/supervisor counts, exact-version acknowledgement, stale-screen denial, real retry deduplication, reassignment/history/reload and revoked/cross-company denial PASS',fixture)
 }catch(e){mkdirSync('test-results',{recursive:true});writeFileSync('test-results/crew-stage.json',JSON.stringify({stage,name:e.name}));throw e}finally{for(const c of contexts)await c.close()}
}
